pub fn word_count(text: &str) -> HashMap<String, usize> {
    let mut word_count: HashMap<String, usize> = HashMap::new();

    for word in text
        .split_whitespace()
        .filter(|s| !s.is_empty() && !s.contains('*'))
    {
        *word_count.entry(word.to_lowercase()).or_insert(0) += 1;
    }

    word_count
}

