pub fn from_roman(s: &str) -> Option<u32> {
    let mut value: u32 = 0;
    for (i, c) in s.chars().enumerate() {
        match c {
            'i' => value += i as u32,
            'v' => value += 5 as u32,
            'x' => value += 10 as u32,
            'l' => value += 50 as u32,
            'c' => value += 100 as u32,
            'd' => value += 500 as u32,
            'm' => value += 1000 as u32,
            _ => return None,
        }
    }
    Some(value)
}

