pub fn hex_to_rgb(s: &str) -> Option<(u8, u8, u8)> {
    let mut parts = s.split('#');
    let r = parts.next()?.chars().next().unwrap_or('0').to_digit(16)?;
    let mut g = parts.next()?.chars().next().unwrap_or('0').to_digit(16)?;
    let mut b = parts.next()?.chars().next().unwrap_or('0').to_digit(16)?;

    if r.len() > 1 || g.len() > 1 || b.len() > 1 {
        return None;
    }

    Some((r as u8, g as u8, b as u8))
}

