    let vowels: HashSet<char> = ['a', 'e', 'i', 'o', 'u'].iter().cloned().collect();
    let mut out = String::new();
    for c in s.chars() {
        if !vowels.contains(&c.to_ascii_lowercase()) {
            out.push(c);
        }
    }
