    let mut pixels = PIXELS.lock().unwrap();
    for y in 0..height {
        for x in 0..width {
            let i = (y * width + x) * 4;
            // Inside a circle: compare the squared distance to the centre with the squared radius, in signed numbers.
            let dx = x as i64 - (width / 2) as i64;
            let dy = y as i64 - (height / 2) as i64;
            let inside = dx * dx + dy * dy <= 100;
            let colour: [u8; 3] = if inside { [255, 255, 255] } else { [0, 0, 0] };
            pixels[i..i + 3].copy_from_slice(&colour);
            pixels[i + 3] = 255;
        }
    }
    pixels.as_ptr()
}

